python.code:
def timer(func):
    def wrapper(*args, **kwargs):
        print("Starting...")
        result = func(*args, **kwargs)
        print("Finished.")
        return result
    return wrapper

@timer
def greet(name):
    print(f"Hello {name}")

greet("Sam")   # Starting... Hello Sam Finished.

