// Conceptual equivalent using a wrapper
interface Task { void run(); }

class TimedTask implements Task {
    private final Task inner;
    TimedTask(Task t) { inner = t; }
    public void run() {
        System.out.println("Starting...");
        inner.run();
        System.out.println("Finished.");
    }
}
